// "आज" home (owner-approved 1 Nov 2026, docs/UX_REVIEW_2026-11.md): the next lesson in the guide's order,
// this week's six days, and the way into the whole year. Pure HTML builder; app.mjs supplies data and helpers.
// Never a gate: every lesson stays one tap away and all other routes keep working.
export function renderToday({t,e,grade,gradeText,subjectText,position,week,ask,goals,readiness,card,dayLabel,lessonHref,hasGoals}){
 const next=position.next;
 const prompt=ask?`<section class="taught-prompt" aria-labelledby="taught-prompt-title"><p id="taught-prompt-title">${t('पिछली बार खोला पाठ','Last lesson you opened')}: <strong>${t('सप्ताह','Week')} ${ask.week} · ${t('दिन','Day')} ${ask.day}</strong> — ${e(ask.title)}</p><p class="taught-prompt-question">${t('क्या यह पढ़ा दिया?','Have you taught it?')}</p><div class="taught-prompt-actions"><button class="button primary" data-prompt-taught="${e(ask.id)}">✓ ${t('हाँ, पढ़ा दिया','Yes, taught')}</button><button class="button" data-prompt-later="${e(ask.id)}">${t('अभी नहीं','Not yet')}</button></div></section>`:'';
 const ready=readiness?`<section class="today-readiness"><h2>${t('सप्ताह','Weeks')} ${readiness.from}–${readiness.to}: ${e(readiness.label)}</h2><p>${t('इन सप्ताहों की योजना इस संदर्शिका में नहीं है। संदर्शिका के पाठ सप्ताह','These weeks are not planned in this guide. The guide’s lessons start in week')} ${readiness.to+1}${t(' से शुरू होते हैं।','.')}</p></section>`:'';
 const goalLine=goals.length?`<div class="today-goals">${goals.map(g=>`<a class="today-goal" href="#/guide/goal/${encodeURIComponent(g.id)}"><span>🎯 ${e(g.title)}</span>${g.position?`<b>${t('पाठ','Lesson')} ${g.position} / ${g.total}</b>`:''}</a>`).join('')}</div>`:'';
 const nextBlock=next?`<section class="today-next" aria-labelledby="today-next-title"><h2 id="today-next-title">${position.taught?t('अगला पाठ','Next lesson'):t('पहला पाठ','First lesson')}</h2>${card(next)}${goalLine}</section>`
  :position.finished?`<section class="panel"><h2>✓ ${t('इस कक्षा के सभी पाठ पढ़ाए गए चिह्नित हैं।','Every lesson for this grade is marked taught.')}</h2><a class="button" href="#/find">${t('सभी पाठ','All lessons')} →</a></section>`:'';
 const tiles=week.lessons.length?`<section class="today-week" aria-labelledby="today-week-title"><h2 id="today-week-title">${t('यह सप्ताह','This week')} · ${t('सप्ताह','Week')} ${week.number}</h2><div class="today-days">${week.lessons.map(l=>{const label=dayLabel(l);const done=week.completed[l.id],now=next&&l.id===next.id;return `<a class="today-day${l.structure==='weekly-template'?' weekly':''}${done?' done':''}${now?' now':''}" href="${lessonHref(l)}" data-open="${e(l.id)}" ${now?'aria-current="step"':''}><b>${t('दिन','Day')} ${l.day}${done?' ✓':''}</b><span>${e(label||t('नया पाठ','New lesson'))}</span></a>`;}).join('')}</div><p class="small">${t('हरा निशान: पढ़ाया गया। गहरा किनारा: अगला पाठ।','Green tick: taught. Dark border: next lesson.')}</p></section>`:'';
 return `<h1 class="today-title">${t('आज','Today')}</h1>${prompt}${ready}${nextBlock}${tiles}<nav class="list-rows" aria-label="${t('और रास्ते','More ways in')}"><a class="list-row" href="#/saved"><span class="list-row-icon" aria-hidden="true">☆</span><span class="list-row-text"><strong>${t('मेरी सूची','My list')}</strong><span>${t('जिन पाठों को आपने सहेजा है','Lessons you have saved')}</span></span><span class="list-row-go" aria-hidden="true">›</span></a><a class="list-row" href="#/help" data-help-link><span class="list-row-icon" aria-hidden="true">?</span><span class="list-row-text"><strong>${t('मदद','Help')}</strong><span>${t('ऐप कैसे इस्तेमाल करें','How to use the app')}</span></span><span class="list-row-go" aria-hidden="true">›</span></a></nav>`;
}
